#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import sys

def convert_16x16_sprites(input_path, output_path, asset_name):
    try:
        with open(input_path, "r") as f_in, open(output_path, "w") as f_out:

            # --- Write the auto-generated warning header ---
            f_out.write("; " + "=" * 65 + "\n")
            f_out.write("; AUTOGENERATED 16x16 SPRITE FILE - DO NOT EDIT MANUALLY\n")
            f_out.write("; MSX Hardware Order: Top-Left, Bottom-Left, Top-Right, Bottom-Right\n")
            f_out.write("; " + "=" * 65 + "\n\n")

            f_out.write(f"{asset_name}_start:\n")

            current_label = ""
            top_left = []
            top_right = []
            bottom_left = []
            bottom_right = []
            row = 0

            for line in f_in:
                line = line.strip()

                # Skip empty lines
                if not line:
                    continue

                # Handle the sprite label
                if line.startswith("--"):
                    current_label = line.replace("--", "").strip()
                    top_left = []
                    top_right = []
                    bottom_left = []
                    bottom_right = []
                    row = 0
                    f_out.write(f"_{current_label}_pattern:\n")
                
                # Handle the binary rows
                else:
                    parts = line.split()
                    if len(parts) == 2:
                        left_bits, right_bits = parts
                        
                        # Rows 0-7 belong to the Top blocks
                        if row < 8:
                            top_left.append(left_bits)
                            top_right.append(right_bits)
                        # Rows 8-15 belong to the Bottom blocks
                        else:
                            bottom_left.append(left_bits)
                            bottom_right.append(right_bits)
                        
                        row += 1

                        # Once we hit 16 rows, write the 32 bytes in MSX VDP order
                        if row == 16:
                            f_out.write("  ; Top-Left\n")
                            for b in top_left:
                                f_out.write(f"  defb %{b}\n")
                            
                            f_out.write("  ; Bottom-Left\n")
                            for b in bottom_left:
                                f_out.write(f"  defb %{b}\n")
                                
                            f_out.write("  ; Top-Right\n")
                            for b in top_right:
                                f_out.write(f"  defb %{b}\n")
                                
                            f_out.write("  ; Bottom-Right\n")
                            for b in bottom_right:
                                f_out.write(f"  defb %{b}\n")

            f_out.write(f"{asset_name}_end:\n")

        print(f"Successfully converted 16x16 sprites to {output_path}")

    except FileNotFoundError:
        print(f"Error: Could not find the input file '{input_path}'")
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: python sprite_16x16_parser.py <input_file.txt> <output_file.asm> <asset_name>")
        sys.exit(1)

    convert_16x16_sprites(sys.argv[1], sys.argv[2], sys.argv[3])
